(()=>{'use strict';const form=document.getElementById('ai-guide-form');if(!form)return;const state=document.getElementById('ai-guide-status'),question=document.getElementById('ai-guide-question'),consent=document.getElementById('ai-guide-consent'),result=document.getElementById('ai-guide-result'),button=form.querySelector('button');let busy=false;fetch('/api/hizmet-asistani',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{if(x.enabled){form.hidden=false;state.textContent='Yapay zekâ bağlantısı kullanılabilir. Genel sorunuzu yazmadan önce gönderim açıklamasını okuyun.'}else state.textContent='Yapay zekâ bağlantısı henüz etkin değil. Aşağıdaki hizmet rehberleri ve iletişim seçenekleri kullanılabilir.'}).catch(()=>{state.textContent='Yapay zekâ bağlantısı şu anda kullanılamıyor. Aşağıdaki hizmet rehberlerini kullanabilirsiniz.'});form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!form.reportValidity())return;busy=true;button.disabled=true;result.replaceChildren();state.textContent='Sorunuz yanıtlanıyor…';const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),42000);try{const response=await fetch('/api/hizmet-asistani',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:question.value,consent:consent.checked}),signal:controller.signal});let data;try{data=await response.json()}catch{throw Error('Şu an yanıt alınamadı. Hazır rehberleri kullanabilirsiniz.')}if(!response.ok)throw Error(data.message||'Şu an yanıt alınamadı. Hazır rehberleri kullanabilirsiniz.');const p=document.createElement('p');p.textContent=data.answer;result.append(p);const title=document.createElement('h2');title.textContent='İlgili rehberler';result.append(title);for(const s of data.sources||[]){if(!s.url?.startsWith('/')||s.url.startsWith('//'))continue;const a=document.createElement('a');a.href=s.url;a.textContent=s.title;const row=document.createElement('p');row.append(a);result.append(row)}const note=document.createElement('p');note.className='growth-note';note.textContent=data.disclaimer;result.append(note);state.textContent='Yanıt hazır.';question.value='';consent.checked=false;}catch(error){state.textContent=error.name==='AbortError'?'Yanıt zamanında alınamadı. Hazır rehberleri kullanabilirsiniz.':error.message}finally{clearTimeout(timeout);busy=false;button.disabled=false}})})();
